import * as fs from 'node:fs';

/** Undo only a missing path generated by the former ASAR-specific auto-healer. */
export function clearMissingLegacyVectorPath(config:any,gatewayRoot:string,exists:(file:string)=>boolean=fs.existsSync):boolean{
 if(gatewayRoot.endsWith('.asar'))return false;
 const vector=config?.memory?.search?.store?.vector,value=vector?.extensionPath;
 if(typeof value!=='string'||!/(?:^|[\\/])gateway\.asar\.unpacked[\\/]node_modules[\\/]sqlite-vec-(?:windows|linux|darwin)-(?:x64|arm64)[\\/]vec0\.(?:dll|so|dylib)$/i.test(value)||exists(value))return false;
 delete vector.extensionPath;return true;
}
